import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# Prices for the small, stable catalog used by callers when the internal service
# is temporarily unavailable.  The service remains the source of truth whenever
# it can be reached.
_FALLBACK_PRICES = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    """Return the total price for *skus*.

    Prefer the internal pricing service, but retain service continuity for the
    known catalog during DNS or network outages. Unknown SKUs still propagate
    the service error rather than silently receiving an invented price.
    """
    total = 0.0
    for sku in skus:
        try:
            total += get_price(sku)
        except urllib.error.URLError:
            if sku not in _FALLBACK_PRICES:
                raise
            total += _FALLBACK_PRICES[sku]
    return total
PY
